begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
-- All fixture settings/counters, identities and assignments roll back together.
update public.app_settings set generation_paused=false,claims_paused=true,limits=limits||'{"educationExecutionVerified":true,"enabledGenerationModes":["education"],"globalByteLimitConfigured":true}';
update public.usage_accounts set byte_limit=1000000000 where scope='global';
delete from private.provider_daily_usage where day=(clock_timestamp() at time zone 'UTC')::date;
insert into auth.users(id,email,raw_user_meta_data) values('d3300000-0000-4000-8000-000000000001','operator-sql@example.invalid','{"display_name":"Operator fixture"}'),('d3300000-0000-4000-8000-000000000002','owner-sql@example.invalid','{"display_name":"Tester fixture","role":"operator"}');
update public.profiles set role='operator' where id='d3300000-0000-4000-8000-000000000001';
insert into public.usage_accounts(scope,owner_id,byte_limit,output_limit) values('user','d3300000-0000-4000-8000-000000000002',200000000,3);
insert into public.projects(id,owner_id,title,mode,draft_input) values('d3310000-0000-4000-8000-000000000001','d3300000-0000-4000-8000-000000000002','private-marker-do-not-expose','education','{"mode":"education","topic":"private-marker-do-not-expose","audience":"beginner","intendedUse":"personal-learning","sources":[]}');
insert into public.workers(id,label,enabled,protocol_version,capabilities,health,last_seen_at) values('d3320000-0000-4000-8000-000000000001','private-marker-do-not-expose',true,1,'{"modes":["education"],"orientations":["landscape","portrait"],"schemaVersions":[1],"compositionVersion":"v1"}','{"executionReady":true,"secret":"private-marker-do-not-expose"}',clock_timestamp());
insert into public.worker_credentials(worker_id,token_hash,expires_at) values('d3320000-0000-4000-8000-000000000001',repeat('c',64),now()+interval '1 hour');
create function pg_temp.actor(who integer) returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub',case when who=1 then 'd3300000-0000-4000-8000-000000000001' else 'd3300000-0000-4000-8000-000000000002' end,'role','authenticated')::text,true);end$$;
select ok(not has_function_privilege('anon','public.operator_console(text,jsonb)','execute'),'Anonymous operator RPC denied');
select ok(not has_function_privilege('authenticated','private.operator_console_internal(text,jsonb)','execute'),'Internal operations implementation cannot bypass entry authorization');
select ok(not has_column_privilege('authenticated','public.profiles','role','update'),'Users cannot promote themselves');
select pg_temp.actor(2);
select throws_ok($$select public.operator_console('health')$$,'42501',null::text,'Self-declared metadata role does not authorize operations');
select pg_temp.actor(1);
update public.profiles set status='disabled' where id='d3300000-0000-4000-8000-000000000001';
select throws_ok($$select public.operator_console('health')$$,'42501',null::text,'Disabled operator denied');
update public.profiles set status='active' where id='d3300000-0000-4000-8000-000000000001';
select ok(public.operator_console('health')::text not like '%private-marker%','Health excludes arbitrary worker health, labels and input');
select ok(public.operator_console('health')::text not like '%token_hash%','Health excludes credential hashes');
select is(public.operator_console('health')->'dailyBudget'->>'providerBalance','unknown','Application counters never claim remaining provider credits');
select throws_ok($$select public.operator_console('health','{"actor":"d3300000-0000-4000-8000-000000000002"}')$$,'22023',null::text,'Actor spoofing rejected');
set local role authenticated;
select is(jsonb_typeof(public.operator_console('health')->'controls'),'object','Real authenticated operator role can call the definer safely');
select is((select count(*) from public.projects where owner_id='d3300000-0000-4000-8000-000000000002'),0::bigint,'Operator role does not bypass tester project RLS');
select throws_ok($$select * from private.operator_receipts$$,'42501',null::text,'Real authenticated role cannot inspect private receipts');
reset role;
create temporary table op_controls as select version,limits from public.app_settings where id='global';
create temporary table op_reply(data jsonb);
insert into op_reply select public.operator_console('controls',jsonb_build_object('requestId','d3330000-0000-4000-8000-000000000001','reason','maintenance','expectedVersion',(select version from op_controls),'generationPaused',true));
select is((select version from public.app_settings where id='global'),(select version+1 from op_controls),'Pause changes version once');
select is((select limits from public.app_settings where id='global'),(select limits from op_controls),'Pause cannot increase limits or change provider/mode configuration');
select is(public.operator_console('controls',jsonb_build_object('requestId','d3330000-0000-4000-8000-000000000001','reason','maintenance','expectedVersion',(select version from op_controls),'generationPaused',true)),(select data from op_reply),'Lost-response replay returns original receipt');
select is((select count(*) from public.operator_audit where actor_id='d3300000-0000-4000-8000-000000000001'),1::bigint,'Replay does not duplicate audit');
select is(public.operator_console('controls',jsonb_build_object('requestId','d3330000-0000-4000-8000-000000000001','reason','maintenance','expectedVersion',(select version from op_controls),'generationPaused',false))->>'operatorError','VERSION_CONFLICT','Same receipt cannot carry changed controls');
select is(public.operator_console('controls',jsonb_build_object('requestId',gen_random_uuid(),'reason','maintenance','expectedVersion',(select version from op_controls),'claimsPaused',false))->>'operatorError','VERSION_CONFLICT','Stale control version cannot overwrite current pause');
select throws_ok($$select public.operator_console('controls','{"requestId":"d3330000-0000-4000-8000-000000000003","reason":null,"expectedVersion":1,"claimsPaused":false}')$$,'22023',null::text,'Null reason rejected by direct RPC');
select throws_ok($$select public.operator_console('controls','{"requestId":"d3330000-0000-4000-8000-000000000003","reason":"maintenance","expectedVersion":1,"claimsPaused":false,"limits":{}}')$$,'22023',null::text,'Spending controls cannot be smuggled into pause request');
create temporary table op_noop as select version,updated_at,updated_by from public.app_settings where id='global';
select public.operator_console('controls',jsonb_build_object('requestId',gen_random_uuid(),'reason','maintenance','expectedVersion',(select version from op_noop),'generationPaused',true));
select is((select version from public.app_settings where id='global'),(select version from op_noop),'No-op does not advance version');
select is((select updated_at from public.app_settings where id='global'),(select updated_at from op_noop),'No-op preserves control modification metadata');
delete from private.operator_windows;
update public.app_settings set generation_paused=false;
create temporary table op_job(job uuid,assignment jsonb,reply jsonb);
create function pg_temp.new_op_job(k text) returns void language plpgsql as $$
begin
 perform pg_temp.actor(2);
 delete from op_job;
 insert into op_job(job)select (public.enqueue_generation('d3310000-0000-4000-8000-000000000001',k,'{"draftVersion":1,"preferences":{"targetSeconds":60,"orientation":"landscape","voiceProfileId":"Kore"},"acknowledgments":{"sourceRights":true,"externalAiProcessing":true,"policyVersion":"v1"}}')->>'jobId')::uuid;
 update public.app_settings set claims_paused=false;
 update op_job set assignment=public.worker_control(repeat('c',64),1,'claim','{"instanceId":"d3340000-0000-4000-8000-000000000001","capabilities":{"modes":["education"],"orientations":["landscape","portrait"],"schemaVersions":[1],"compositionVersion":"v1"}}');
 if (select assignment->>'jobId' is distinct from job::text from op_job) then raise exception 'Unexpected fixture claim; rollback required';end if;
 update public.app_settings set claims_paused=true;
 perform pg_temp.actor(1);
end$$;
create function pg_temp.expire_op_job()returns void language plpgsql as $$begin
 update public.jobs set lease_expires_at=clock_timestamp()-interval '1 second',last_heartbeat_at=clock_timestamp()-interval '10 seconds' where id=(select job from op_job);
 update public.worker_slots set lease_expires_at=clock_timestamp()-interval '1 second' where job_id=(select job from op_job);
end$$;
create function pg_temp.reconcile_op_job(request uuid default gen_random_uuid())returns jsonb language sql as $$select public.operator_console('reconcile',jsonb_build_object('requestId',request,'reason','maintenance','jobId',job,'expectedLeaseToken',assignment->>'leaseToken'))from op_job$$;
select pg_temp.new_op_job('lease');
select public.operator_console('controls',jsonb_build_object('requestId',gen_random_uuid(),'reason','maintenance','expectedVersion',(select version from public.app_settings where id='global'),'generationPaused',true));
select is(public.worker_control(repeat('c',64),1,'heartbeat',jsonb_build_object('instanceId','d3340000-0000-4000-8000-000000000001','health','{"executionReady":true}'::jsonb,'assignment',jsonb_build_object('jobId',(select job from op_job),'leaseToken',(select assignment->>'leaseToken' from op_job))))->>'cancelRequested','false','Pause does not cancel an active assignment');
update public.app_settings set generation_paused=false;
select is(pg_temp.reconcile_op_job()->>'operatorError','STATE_CONFLICT','Live assignment is never fenced');
select is((select status from public.jobs where id=(select job from op_job)),'running','Live worker remains running');
select pg_temp.expire_op_job();
update public.app_settings set claims_paused=false;
select is(pg_temp.reconcile_op_job()->>'operatorError','STATE_CONFLICT','Expired repair requires claims to be paused first');
update public.app_settings set claims_paused=true;
insert into public.checkpoints(project_id,owner_id,revision_id,job_id,stage,unit_key,dependency_hash,producer_version,manifest,producing_lease_token) select project_id,owner_id,revision_id,id,'understand','fixture',repeat('a',64),'w30-synthetic','{}',lease_token from public.jobs where id=(select job from op_job);
update public.jobs set repair_count=1,active_ms=12000 where id=(select job from op_job);
update op_job set reply=pg_temp.reconcile_op_job('d3350000-0000-4000-8000-000000000001');
select is((select reply->>'status' from op_job),'queued','Expired safe assignment returns to queue');
select is((select repair_count from public.jobs where id=(select job from op_job)),1,'Repair budget preserved');
select ok((select active_ms>=12000 from public.jobs where id=(select job from op_job)),'Accumulated processing time preserved');
select is((select count(*) from public.checkpoints where job_id=(select job from op_job)),1::bigint,'Completed checkpoint retained');
select is((select state from public.usage_reservations where job_id=(select job from op_job)),'reserved','Queued recovery retains reservation');
select is(pg_temp.reconcile_op_job('d3350000-0000-4000-8000-000000000001'),(select reply from op_job),'Reconcile receipt replay does not fence twice');
select throws_ok($$select public.worker_control(repeat('c',64),1,'heartbeat',jsonb_build_object('instanceId','d3340000-0000-4000-8000-000000000001','health','{}'::jsonb,'assignment',jsonb_build_object('jobId',(select job from op_job),'leaseToken',(select assignment->>'leaseToken' from op_job))))$$,'P1503',null::text,'Old worker callback is rejected after reconciliation');
select pg_temp.actor(2);select public.cancel_generation((select job from op_job));select pg_temp.actor(1);
delete from private.operator_windows;
select pg_temp.new_op_job('unknown');
insert into public.provider_attempts(job_id,run_id,operation_key,operation_attempt,dispatch_nonce,provider,model_id,request_hash,status)select j.id,r.id,'fixture',1,gen_random_uuid(),'gemini','fixture',repeat('b',64),'dispatched' from public.jobs j join public.job_runs r on r.job_id=j.id and r.lease_token=j.lease_token where j.id=(select job from op_job);
update public.jobs set provider_attempt_count=1 where id=(select job from op_job);
select pg_temp.expire_op_job();
select is(pg_temp.reconcile_op_job()->>'status','failed','Uncertain provider request requires review instead of blind retry');
select is((select status from public.provider_attempts where job_id=(select job from op_job)),'outcome_unknown','Unconfirmed dispatched request stays uncertain');
select is((select provider_attempt_count from public.jobs where id=(select job from op_job)),1,'Provider attempt budget is not refunded');
select is((select attempts from private.provider_daily_usage where day=(clock_timestamp() at time zone 'UTC')::date and scope_key='global'),1,'Daily provider usage is not refunded');
select is((select state from public.usage_reservations where job_id=(select job from op_job)),'released','Terminal reconciliation releases remaining reservation once');
select pg_temp.new_op_job('cancel');
select pg_temp.actor(2);select public.cancel_generation((select job from op_job));select pg_temp.actor(1);select pg_temp.expire_op_job();
select is(pg_temp.reconcile_op_job()->>'status','cancelled','Cancellation wins over requeue');
select is((select job_id from public.worker_slots where slot_name='processing'),null::uuid,'Expired cancellation clears its exact slot');
select ok(public.operator_console('jobs')::text not like '%private-marker%','Job projection omits title, immutable inputs and arbitrary errors');
insert into public.operator_audit(actor_id,action,resource_type,safe_metadata)select 'd3300000-0000-4000-8000-000000000001','operator.controls','app_settings','{"secret":"private-marker-do-not-expose"}' from generate_series(1,27);
delete from private.operator_windows;
update op_reply set data=public.operator_console('audit');
select is(jsonb_array_length((select data->'items' from op_reply)),25,'Audit page bounded to 25');
select ok((select data->>'nextCursor' is not null from op_reply),'Audit has a deterministic next cursor');
select ok(public.operator_console('audit')::text not like '%private-marker%','Audit projection omits arbitrary metadata');
select ok(jsonb_array_length(public.operator_console('audit',jsonb_build_object('before',(select data->>'nextCursor' from op_reply)))->'items')>0,'Cursor opens following audit page');
delete from private.operator_windows;
do $$begin for i in 1..10 loop perform public.operator_console('controls',jsonb_build_object('requestId',gen_random_uuid(),'reason','release_check','expectedVersion',(select version from public.app_settings where id='global'),'claimsPaused',true));end loop;end$$;
select is(public.operator_console('controls',jsonb_build_object('requestId',gen_random_uuid(),'reason','release_check','expectedVersion',(select version from public.app_settings where id='global'),'claimsPaused',true))->>'rateLimited','true','Eleventh mutation is throttled across RPC calls');
select is((select mutations from private.operator_windows where actor='d3300000-0000-4000-8000-000000000001'),10,'Persisted mutation counter is bounded');
delete from private.operator_windows;
do $$begin for i in 1..60 loop perform public.operator_console('health');end loop;end$$;
select is(public.operator_console('health')->>'rateLimited','true','Sixty-first inspection is throttled');
select ok(not has_table_privilege('authenticated','private.operator_receipts','select'),'Operator cannot read internal receipt bodies directly');
select * from finish();
rollback;
